/**
 * The SSR golden corpus (#1646).
 *
 * Every case renders a template through the public renderer and returns the
 * bytes. `ssr-golden.test.js` compares each result with the committed file
 * under `fixtures/`, so a renderer change that moves a single byte on any of
 * these shapes fails with a named case rather than a vague suite failure
 * somewhere downstream. The corpus was generated by the three-pass renderer
 * BEFORE the one-pass rewrite, so it is the contract the rewrite is held to.
 *
 * Deliberate differences are updated here one commit at a time, each naming
 * the reason in its message. Regenerate with:
 *
 *   WEBJS_GOLDEN_UPDATE=1 node --test packages/core/test/rendering/ssr-golden/ssr-golden.test.js
 *
 * Every component here carries a `gold-` tag prefix so it cannot collide with
 * a tag another suite registers in the same process.
 */
import { html, css, WebComponent, Suspense, signal, renderToString, renderToStream } from '../../../index.js';
import { repeat } from '../../../src/repeat.js';
import { unsafeHTML, live, keyed, guard, cache, until } from '../../../src/directives.js';
import { setFormActionResolver } from '../../../src/form-action.js';

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

class Badge extends WebComponent({ label: String, count: Number, on: Boolean }) {
  constructor() { super(); this.label = ''; this.count = 0; this.on = false; }
  render() { return html`<span class="badge">${this.label}:${this.count}:${this.on ? 'on' : 'off'}</span>`; }
}
Badge.register('gold-badge');

class Reflecting extends WebComponent({ mode: { type: String, reflect: true }, size: { type: Number, reflect: true } }) {
  constructor() { super(); this.mode = 'auto'; this.size = 3; }
  willUpdate() { if (this.size > 5) this.setAttribute('data-large', ''); }
  render() { return html`<i>${this.mode}/${this.size}</i>`; }
}
Reflecting.register('gold-reflecting');

class Shell extends WebComponent {
  render() {
    return html`<header><slot name="head">NO-HEAD</slot></header><main><slot></slot></main><footer><slot name="foot">no actions</slot></footer>`;
  }
}
Shell.register('gold-shell');

class Forwarder extends WebComponent {
  render() { return html`<gold-shell><b slot="head">fwd-head</b><slot></slot></gold-shell>`; }
}
Forwarder.register('gold-forwarder');

class Decorator extends WebComponent {
  // Defines no render method, so it is a transparent wrapper whose children
  // stay in place.
}
Decorator.register('gold-decorator');

class EmptyRender extends WebComponent {
  render() { return html``; }
}
EmptyRender.register('gold-empty');

class Shadowy extends WebComponent({ tone: String }) {
  static shadow = true;
  static styles = css`:host { display: block } p { color: red }`;
  constructor() { super(); this.tone = 'calm'; }
  render() { return html`<p>${this.tone}</p><slot name="x"></slot><slot></slot>`; }
}
Shadowy.register('gold-shadowy');

class ShadowList extends WebComponent {
  static shadow = true;
  static styles = [css`a { b: c }`, css`d { e: f }`];
  render() { return html`<ul><li><slot></slot></li></ul>`; }
}
ShadowList.register('gold-shadow-list');

class Parent extends WebComponent({ depth: Number }) {
  constructor() { super(); this.depth = 1; }
  render() {
    if (this.depth >= 3) return html`<em>leaf ${this.depth}</em>`;
    return html`<section data-depth=${this.depth}><gold-parent depth=${this.depth + 1}></gold-parent></section>`;
  }
}
Parent.register('gold-parent');

class Closest extends WebComponent({ tag: String }) {
  constructor() { super(); this.tag = ''; }
  render() {
    const host = this.closest(this.tag);
    return html`<q>${host ? host.__ssrTag : 'none'}</q>`;
  }
}
Closest.register('gold-closest');

class Thrower extends WebComponent({ mode: String }) {
  constructor() { super(); this.mode = ''; }
  render() {
    if (this.mode === 'custom') throw new Error('custom boom');
    throw new Error('plain boom');
  }
  renderError(err) {
    if (this.mode === 'custom') return html`<div class="custom-err">${err.message}</div>`;
    return undefined;
  }
}
Thrower.register('gold-thrower');

class ShadowThrower extends WebComponent {
  static shadow = true;
  static styles = css`:host { color: red }`;
  render() { throw new Error('shadow boom'); }
}
ShadowThrower.register('gold-shadow-thrower');

class AsyncItem extends WebComponent({ label: String }) {
  constructor() { super(); this.label = ''; }
  async render() {
    await Promise.resolve();
    return html`<p class="item">${this.label}</p>`;
  }
}
AsyncItem.register('gold-async-item');

class AsyncThrower extends WebComponent {
  async render() { await Promise.resolve(); throw new Error('async boom'); }
}
AsyncThrower.register('gold-async-thrower');

class Rich extends WebComponent({ when: Object, tags: Array, meta: Object }) {
  constructor() { super(); this.when = null; this.tags = []; this.meta = null; }
  render() {
    const when = this.when instanceof Date ? this.when.toISOString() : String(this.when);
    const meta = this.meta instanceof Map ? [...this.meta].map(([k, v]) => `${k}=${v}`).join(',') : String(this.meta);
    return html`<p>${when}|${this.tags.join('+')}|${meta}</p>`;
  }
}
Rich.register('gold-rich');

class AttrReader extends WebComponent({ dataValue: String }) {
  constructor() { super(); this.dataValue = ''; }
  render() {
    return html`<p>${this.getAttribute('title')}|${this.hasAttribute('hidden') ? 'hidden' : 'shown'}|${this.dataValue}</p>`;
  }
}
AttrReader.register('gold-attr-reader');

class FormHost extends WebComponent {
  render() {
    return html`<form action=${submitFeedback}><input name="q"><button formaction=${otherAction}>Alt</button></form>`;
  }
}
FormHost.register('gold-form-host');

class SlotWithFallbackHole extends WebComponent({ fb: String }) {
  constructor() { super(); this.fb = 'fallback'; }
  render() { return html`<slot name="a">${this.fb}</slot><slot name="a">second-${this.fb}</slot>`; }
}
SlotWithFallbackHole.register('gold-slot-fb');

class DynamicSlotName extends WebComponent({ which: String }) {
  constructor() { super(); this.which = 'a'; }
  render() { return html`<slot name=${this.which}></slot>`; }
}
DynamicSlotName.register('gold-dyn-slot');

class Counter extends WebComponent({ count: Number }) {
  constructor() { super(); this.count = 0; }
  render() { return html`<button @click=${() => this.add()}>Add 1 to ${this.count}?</button>`; }
}
Counter.register('gold-counter');

class RawHost extends WebComponent {
  render() { return html`<style>gold-raw-host b { color: ${'red'} }</style><script>var x = ${'1 < 2'};</script><b>${'<i>'}</b>`; }
}
RawHost.register('gold-raw-host');

// ---------------------------------------------------------------------------
// Form actions
// ---------------------------------------------------------------------------

async function submitFeedback() { return { success: true }; }
async function otherAction() { return { success: true }; }
const ACTIONS = new Map([[submitFeedback, 'h0ld3n/submitFeedback'], [otherAction, 'h0ld3n/otherAction']]);
setFormActionResolver((fn) => ACTIONS.get(fn) ?? null);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function drain(stream) {
  const chunks = [];
  for await (const c of stream) chunks.push(typeof c === 'string' ? c : new TextDecoder().decode(c));
  return chunks;
}

/** Stream chunks joined with a visible separator so chunk BOUNDARIES are pinned too. */
async function chunked(value, opts) {
  return (await drain(renderToStream(value, opts))).join('\n<!--CHUNK-->\n');
}

/** Render with console.error silenced (the error-isolation cases log on purpose). */
async function quiet(fn) {
  const orig = console.error;
  console.error = () => {};
  try { return await fn(); } finally { console.error = orig; }
}

function ctx() { return { pending: [], nextId: 1, usedComponents: new Set() }; }

const LOREM = 'lorem ipsum dolor sit amet '.repeat(20);

